using GameShelf.Core;
using GameShelf.NetworkSession;
using System.Text;
using System.Text.Json;
static class BrokerCases
{
    static readonly string server=new('1',32),user=new('2',32),game=new('3',32),lease=new('4',32);
    static WindowsLeaseContext Context(double expires){var entry=new LibraryEntry("Play.exe","native",null);var variant=new LibraryVariant(game,"windows",null,[entry],null,true);return new(game,server,user,variant,entry,new(lease,expires,server,user,new(game),new("fixture.invalid",2445,"synthetic",null,"fixture","sensitive-marker"),new("Play.exe","reviewed-relative-saves",true)));}
    static double Now=>DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()/1000d;
    static void Check(bool value){if(!value)throw new Exception("Broker invariant failed");}
    public static async Task FullContextRoundTrip(){var value=Context(Now+90);value=value with{Lease=value.Lease with{WindowsLaunch=value.Lease.WindowsLaunch! with{ReviewedProfileID="fixture-review",ProfileRevision=1,EntrySHA256=new string('a',64),RulesSHA256=new string('b',64),EvidenceSHA256=new string('c',64),SourceSignature=new string('d',64),SavePaths=[new("savedata","directory")],Synthetic=true}}};var request=new BrokerRequest(1,Guid.NewGuid(),1,BrokerCommand.Connect,value);using var stream=new MemoryStream();await BrokerWire.Write(stream,request,CancellationToken.None);stream.Position=0;var copy=await BrokerWire.Read<BrokerRequest>(stream,CancellationToken.None);copy.Context!.Validate(DateTimeOffset.UtcNow);Check(copy.Operation==request.Operation&&copy.Context.CanonicalID==value.CanonicalID&&copy.Context.ServerID==value.ServerID&&copy.Context.UserID==value.UserID&&copy.Context.Entry==value.Entry&&copy.Context.Lease.Share==value.Lease.Share&&copy.Context.Lease.LeaseID==value.Lease.LeaseID&&JsonSerializer.Serialize(copy.Context.Lease.WindowsLaunch)==JsonSerializer.Serialize(value.Lease.WindowsLaunch));}
    public static Task PeerAndNonce(){var parent=new BrokerPeer(10,1,"S-1-5-21-fixture","0000000000000001");var child=new BrokerPeer(11,1,parent.Sid,"0000000000000002");BrokerHandshake.Pair(parent,child,11);foreach(var invalid in new[]{child with{Pid=12},child with{Sid="other"},child with{AuthenticationId=parent.AuthenticationId},child with{Session=0}}){try{BrokerHandshake.Pair(parent,invalid,11);throw new Exception("Bad peer accepted");}catch(BrokerFailure e)when(e.Stage==BrokerStage.Identity){}}BrokerHandshake.Nonce(new string('a',64),new string('a',64));try{BrokerHandshake.Nonce(new string('a',64),new string('b',64));throw new Exception("Bad nonce accepted");}catch(BrokerFailure e)when(e.Stage==BrokerStage.Identity){}return Task.CompletedTask;}
    public static async Task FrameBounds(){using var a=new MemoryStream(BitConverter.GetBytes(BrokerWire.Limit+1));try{await BrokerWire.Read<BrokerRequest>(a,CancellationToken.None);throw new Exception();}catch(BrokerFailure e)when(e.Stage==BrokerStage.Protocol){}using var b=new MemoryStream();try{await BrokerWire.Write(b,new string('x',BrokerWire.Limit+1),CancellationToken.None);throw new Exception();}catch(BrokerFailure e)when(e.Stage==BrokerStage.Protocol){Check(b.Length==0);}}
    public static async Task StrictJson(){using var s=new MemoryStream();var bytes=Encoding.UTF8.GetBytes("{\"version\":1,\"unexpected\":true}");s.Write(BitConverter.GetBytes(bytes.Length));s.Write(bytes);s.Position=0;try{await BrokerWire.Read<BrokerRequest>(s,CancellationToken.None);throw new Exception();}catch(BrokerFailure e)when(e.Stage==BrokerStage.Protocol){}}
    public static async Task ProxyDispose(){int calls=0;var p=new BrokerProcessProxy((command,_)=>{calls++;return Task.FromResult(new BrokerStatus(true,true,true,false));});await p.Wait(CancellationToken.None);await p.Stop();int before=calls;await p.DisposeAsync();Check(before==calls);}
    public static async Task Sequence(){var v=new View();Guid id=Guid.NewGuid();await using var e=new BrokerEngine(id,v,(_,_,_)=>Task.CompletedTask);var r=await e.Execute(new(1,Guid.NewGuid(),1,BrokerCommand.Connect,Context(Now+90)),CancellationToken.None);Check(!r.Success&&v.ConnectCount==0);r=await e.Execute(new(1,id,1,BrokerCommand.Connect,Context(Now+90)),CancellationToken.None);Check(r.Success);r=await e.Execute(new(1,id,1,BrokerCommand.Start),CancellationToken.None);Check(!r.Success&&v.StartCount==0);await e.PeerLost();}
    public static async Task CleanupOrdering(){var v=new View();Guid id=Guid.NewGuid();await using var e=new BrokerEngine(id,v,(_,_,_)=>Task.CompletedTask);Check((await e.Execute(new(1,id,1,BrokerCommand.Connect,Context(Now+90)),CancellationToken.None)).Success);Check((await e.Execute(new(1,id,2,BrokerCommand.Start),CancellationToken.None)).Success);var result=await e.Execute(new(1,id,3,BrokerCommand.Disconnect),CancellationToken.None);Check(result.Success&&result.Status is{NativeStopped:true,MappingGone:true});Check(v.Events.SequenceEqual(new[]{"connect","start","stop","dispose","disconnect"}));}
    public static async Task UncertainMapping(){var v=new View{FailDisconnect=true};Guid id=Guid.NewGuid();var e=new BrokerEngine(id,v,(_,_,_)=>Task.CompletedTask);await e.Execute(new(1,id,1,BrokerCommand.Connect,Context(Now+90)),CancellationToken.None);var result=await e.Execute(new(1,id,2,BrokerCommand.Disconnect),CancellationToken.None);Check(!result.Success&&result.Error==BrokerStage.Disconnect);try{await e.DisposeAsync();throw new Exception("Pending dispose succeeded");}catch(BrokerFailure failure)when(failure.Stage==BrokerStage.Disconnect){}}
    public static async Task UnacknowledgedCreation(){var v=new View{FailConnect=true};Guid id=Guid.NewGuid();var e=new BrokerEngine(id,v,(_,_,_)=>Task.CompletedTask);Check(!(await e.Execute(new(1,id,1,BrokerCommand.Connect,Context(Now+90)),CancellationToken.None)).Success);Check(!(await e.Execute(new(1,id,2,BrokerCommand.Disconnect),CancellationToken.None)).Success);Check(!v.Events.Contains("disconnect"));try{await e.DisposeAsync();throw new Exception("Pending dispose succeeded");}catch(BrokerFailure failure)when(failure.Stage==BrokerStage.Disconnect){}}
    public static async Task EofStops(){var v=new View();Guid id=Guid.NewGuid();await using var e=new BrokerEngine(id,v,(_,_,_)=>Task.CompletedTask);await e.Execute(new(1,id,1,BrokerCommand.Connect,Context(Now+90)),CancellationToken.None);await e.Execute(new(1,id,2,BrokerCommand.Start),CancellationToken.None);await e.PeerLost();Check(v.Events.Contains("stop")&&v.Events.Last()=="disconnect");}
    public static async Task DeadlineAndRenewal(){var clock=new Clock();var v=new View();Guid id=Guid.NewGuid();await using var e=new BrokerEngine(id,v,(_,_,_)=>Task.CompletedTask,time:clock);await e.Execute(new(1,id,1,BrokerCommand.Connect,Context(clock.GetUtcNow().ToUnixTimeMilliseconds()/1000d+20)),CancellationToken.None);await e.Execute(new(1,id,2,BrokerCommand.Start),CancellationToken.None);var renew=await e.Execute(new(1,id,3,BrokerCommand.Renew,LeaseID:lease,ExpiresAt:clock.GetUtcNow().ToUnixTimeMilliseconds()/1000d+100),CancellationToken.None);Check(renew.Success);clock.Advance(25);await Task.Delay(100);Check(!v.Events.Contains("stop"));clock.Advance(100);await v.Closed.Task.WaitAsync(TimeSpan.FromSeconds(2));Check(v.Events.Contains("stop"));}
    public static async Task DisposeDrains(){var v=new View();var id=Guid.NewGuid();var e=new BrokerEngine(id,v,(_,_,_)=>Task.CompletedTask);await e.Execute(new(1,id,1,BrokerCommand.Connect,Context(Now+90)),CancellationToken.None);await e.Execute(new(1,id,2,BrokerCommand.Start),CancellationToken.None);await e.DisposeAsync();Check(v.Events.Contains("stop")&&v.Events.Last()=="disconnect");}
    public static async Task DisposeRejectsUncertain(){var v=new View{FailDisconnect=true};var id=Guid.NewGuid();var e=new BrokerEngine(id,v,(_,_,_)=>Task.CompletedTask);await e.Execute(new(1,id,1,BrokerCommand.Connect,Context(Now+90)),CancellationToken.None);try{await e.DisposeAsync();throw new Exception("Uncertain dispose succeeded");}catch(BrokerFailure failure)when(failure.Stage==BrokerStage.Disconnect){}}
    public static async Task RenewCannotResurrect(){var clock=new Clock();var v=new View();var id=Guid.NewGuid();var e=new BrokerEngine(id,v,(_,_,_)=>Task.CompletedTask,time:clock);await e.Execute(new(1,id,1,BrokerCommand.Connect,Context(Now+20)),CancellationToken.None);clock.Advance(30);var result=await e.Execute(new(1,id,2,BrokerCommand.Renew,LeaseID:lease,ExpiresAt:Now+100),CancellationToken.None);await e.DisposeAsync();Check(!result.Success&&result.Error==BrokerStage.Deadline);}
    public static async Task ReviewCannotCrossDeadline(){var clock=new Clock();var v=new View();var id=Guid.NewGuid();var e=new BrokerEngine(id,v,(_,root,_)=>{if(root.Length>0)clock.Advance(30);return Task.CompletedTask;},time:clock);await e.Execute(new(1,id,1,BrokerCommand.Connect,Context(Now+20)),CancellationToken.None);var result=await e.Execute(new(1,id,2,BrokerCommand.Start),CancellationToken.None);await e.DisposeAsync();Check(!result.Success&&v.StartCount==0);}
    public static async Task ConnectCannotAckExpired(){var clock=new Clock();var v=new View{OnConnect=()=>clock.Advance(30)};var id=Guid.NewGuid();var e=new BrokerEngine(id,v,(_,_,_)=>Task.CompletedTask,time:clock);var result=await e.Execute(new(1,id,1,BrokerCommand.Connect,Context(Now+20)),CancellationToken.None);await e.DisposeAsync();Check(!result.Success&&result.Error==BrokerStage.Deadline);}
    public static async Task MetadataCannotCrossDeadline(){var clock=new Clock();var view=new View();var id=Guid.NewGuid();var e=new BrokerEngine(id,view,(_,root,_)=>{if(root.Length==0)clock.Advance(30);return Task.CompletedTask;},time:clock);var reply=await e.Execute(new(1,id,1,BrokerCommand.Connect,Context(Now+20)),CancellationToken.None);await e.DisposeAsync();Check(!reply.Success&&reply.Error==BrokerStage.Deadline&&view.ConnectCount==0);}
    public static async Task RepeatedCleanup(){var v=new View();var id=Guid.NewGuid();var e=new BrokerEngine(id,v,(_,_,_)=>Task.CompletedTask);await e.Execute(new(1,id,1,BrokerCommand.Connect,Context(Now+90)),CancellationToken.None);await e.Execute(new(1,id,2,BrokerCommand.Start),CancellationToken.None);Check((await e.Execute(new(1,id,3,BrokerCommand.Disconnect),CancellationToken.None)).Success);Check((await e.Execute(new(1,id,4,BrokerCommand.Disconnect),CancellationToken.None)).Success);await e.PeerLost();await e.PeerLost();await e.DisposeAsync();await e.DisposeAsync();Check(v.Events.Count(x=>x=="stop")==1&&v.Events.Count(x=>x=="disconnect")==1);}
    public static Task StartupPolicy(){Check(BrokerCredentialName.Parse("fixture").Domain==".");Check(BrokerCredentialName.Parse("fixture@example.invalid").Domain==null);Check(BrokerCredentialName.Parse("DOMAIN\\fixture")==new BrokerCredentialName("fixture","DOMAIN"));Check(BrokerStartupPolicy.ReleaseKillFlag(0x2100,true)==0x100);try{BrokerStartupPolicy.ReleaseKillFlag(0x2000,false);throw new Exception("Unauthenticated startup release");}catch(BrokerFailure e)when(e.Stage==BrokerStage.Identity){}try{BrokerStartupPolicy.ReleaseKillFlag(0x2800,true);throw new Exception("Breakaway policy accepted");}catch(BrokerFailure e)when(e.Stage==BrokerStage.Identity){}return Task.CompletedTask;}
    sealed class Clock:TimeProvider{long offset;public override DateTimeOffset GetUtcNow()=>DateTimeOffset.UtcNow.AddSeconds(Interlocked.Read(ref offset));public void Advance(int seconds)=>Interlocked.Add(ref offset,seconds);}
    sealed class View:IWindowsView
    {
        public bool FailDisconnect,FailConnect;public Action? OnConnect;public int ConnectCount,StartCount;public List<string> Events=[];public TaskCompletionSource Closed=new(TaskCreationOptions.RunContinuationsAsynchronously);
        public Task<string> Connect(SmbShare share,CancellationToken ct){ConnectCount++;if(FailConnect)throw new IOException();Events.Add("connect");OnConnect?.Invoke();return Task.FromResult("private-helper-root");}
        public Task<IGameProcess> Start(string root,string relative,CancellationToken ct){StartCount++;Events.Add("start");return Task.FromResult<IGameProcess>(new Process(this));}
        public Task Disconnect(){if(FailDisconnect)throw new IOException();Events.Add("disconnect");Closed.TrySetResult();return Task.CompletedTask;}
        sealed class Process(View view):IGameProcess{readonly TaskCompletionSource ended=new(TaskCreationOptions.RunContinuationsAsynchronously);public Task Wait(CancellationToken ct)=>ended.Task.WaitAsync(ct);public Task Stop(){view.Events.Add("stop");ended.TrySetResult();return Task.CompletedTask;}public ValueTask DisposeAsync(){view.Events.Add("dispose");return ValueTask.CompletedTask;}}
    }
